head.script:
scwin.vScrenID = "ULDFIS00308.xml";
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd   = ""; // 조회조건 기업코드

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
    scwin.init();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.grd_InsrncRegAsst_OnDblClick = function(row, colid) {
    if (colid === "BAS_YYMM") {
        // 보험가입자산 상세  팝업 오픈
        scwin.insrncRegAsstDtlSrchOpen(row);
    }
};

/**
 *  보험가입자산 상세팝업 
 */
scwin.grd_InsrncRegAsst_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    if (columnId === "basYymm") {
      scwin.insrncRegAsstDtlSrchOpen(rowIndex);
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 *  화면 초기화
 */
scwin.init = function() {
    scwin.search();
};

/**
 *  데이터셋 초기화.
 */
scwin.initDs = function() {
    dlt_InsrncRegAsstRes.removeAll();
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {
    //필수항목 체크.
    scwin.vKisCd = $p.parent().wfm_header.getWindow().scwin.fn_GetKisCd();
    if (scwin.vKisCd=== "") {
        return false;
    }
    return true;
};

/**
 * 보험가입자산 조회
 */
scwin.search = function() {
    //데이터셋 초기화
    scwin.initDs();
    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    const ibxKisCd = $p.parent().wfm_header.getWindow().ibx_KisCd.getValue();

    let url = "/api/listing/nice/individual-notes/" + ibxKisCd + "/insured-assets";
    $c.sbm.setAction(sbm_dlt_InsrncRegAsst, url);
    $c.sbm.execute(sbm_dlt_InsrncRegAsst);
};

/**
 * 보험가입자산 상세 팝업
 */
scwin.insrncRegAsstDtlSrchOpen = async function(pRow) {
        console.log(pRow);
    let url = "/ui/lst/fis/ULDFIS00300_P6.xml";
    let popTitle = "보험가입자산 검색";

    const opts = {
        id: "ULDFIS00300_P6",
        popupName: popTitle,
        width: 700,
        height: 600,
        frameModal: "top",
    };
    const popData = dlt_InsrncRegAsstRes.getRowJSON(pRow);
    await $c.win.openPopup(url, opts, popData);

};

/**
 *  엑셀파일다운로드
 */
scwin.excelDownload = function() {
    if (dlt_InsrncRegAsstRes.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_InsrncRegAsst, {fileName: "보험가입자산", type: "8"});
};
